import sys, itertools, functools
m = 37
PHI = (1 << 37) - 1 >> 1  # 1+x+...+x^36 as bits? careful
PHI = sum(1 << i for i in range(37))  # 1 + x + ... + x^36 (degree 36)
MODPOLY = PHI
DEG = 36

def clmul(a, b):
    r = 0
    while b:
        if b & 1:
            r ^= a
        a <<= 1
        b >>= 1
    return r

def red(a):
    # reduce mod PHI (degree 36)
    while a.bit_length() > DEG:
        sh = a.bit_length() - 1 - DEG
        a ^= PHI << sh
    return a

def mul(a, b):
    return red(clmul(a, b))

def power(a, e):
    r = 1
    while e:
        if e & 1:
            r = mul(r, a)
        a = mul(a, a)
        e >>= 1
    return r

ORDER = (1 << 36) - 1

def zeta_pow(n):
    return red(1 << (n % m))

def eval_rule(supp, j, k):
    # value of sum x^a y^b at (zeta^j, zeta^k)
    v = 0
    for (a, b) in supp:
        v ^= zeta_pow(a * j + b * k)
    return v

def orbit(a, b):
    return set([(a, b), (-a, b), (a, -b), (-a, -b), (b, a), (-b, a), (b, -a), (-b, -a)])

ORBS = [(a, b) for a in range(5) for b in range(a + 1)]
def rule_support(n):
    s = set()
    for i, (a, b) in enumerate(ORBS):
        if n >> i & 1:
            s |= orbit(a, b)
    return s

# element of order 27: g^((2^36-1)/27) for a non-cube g; find one
def find_order27():
    for cand in range(2, 100):
        g = red(cand)
        h = power(g, ORDER // 27)
        if power(h, 9) != 1:
            return h
    raise Exception
W27 = None
def dlog27(v):
    """discrete log mod 27 of v relative to W27 (v^(ORDER/27) = W27^r)"""
    global W27
    if W27 is None:
        W27 = find_order27()
    h = power(v, ORDER // 27)
    p = 1
    for r in range(27):
        if p == h:
            return r
        p = mul(p, W27)
    raise Exception("not found")

if __name__ == "__main__":
    supp = rule_support(4850)
    print(sorted(supp))
    # lines: (1,k) for k in 0..36 and (0,1)
    lines = [(1, k) for k in range(m)] + [(0, 1)]
    res = {}
    for (j, k) in lines:
        v = eval_rule(supp, j, k)
        if v == 0:
            res[(j, k)] = None
        else:
            res[(j, k)] = dlog27(v)
    print(res)
    print("1+zeta dlog27:", dlog27(red(1 | 2)))
    print("zeta dlog27:", dlog27(red(2)))

