        return a
    def mul(a, b):
        r = 0
        while b:
            if b & 1: r ^= a
            a <<= 1; b >>= 1
        return red(r)
    def power(a, e):
        r = 1
        while e:
            if e & 1: r = mul(r, a)
            a = mul(a, a); e >>= 1
        return r
    ORDER = (1 << (m - 1)) - 1
    v3 = 0; t = ORDER
    while t % 3 == 0: t //= 3; v3 += 1
    Q = 3**v3
